'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let pos = 0;
const N = input[pos++];
const M = input[pos++];

const grid = [];
for (let i = 0; i < N; i++) {
  grid.push(input.slice(pos, pos + M));
  pos += M;
}

let cost = [0, 0];
for (let i = 0; i < N; i++) {
  for (let j = 0; j < M; j++) {
    const parity = grid[i][j] % 2;
    for (let start = 0; start <= 1; start++) {
      if (parity !== ((start + i + j) % 2)) cost[start]++;
    }
  }
}

const start = cost[0] <= cost[1] ? 0 : 1;
const output = [String(cost[start])];

for (let i = 0; i < N; i++) {
  const row = [];
  for (let j = 0; j < M; j++) {
    const targetParity = (start + i + j) % 2;
    row.push(String(grid[i][j] + (grid[i][j] % 2 !== targetParity ? 1 : 0)));
  }
  output.push(row.join(' '));
}

console.log(output.join('\n'));
